import re

def parse_size(s: str) -> int:
    if not s:
        raise ValueError('Empty string')

    # Regular expression to match the number and its unit
    pattern = r'^(\d+(\.\d+)?)\s*(B|KB|MB|GB)$'
    match = re.match(pattern, s)
    if not match:
        raise ValueError(f'Malformed input: {s}')

    # Extract the number and unit from the match
    number_str, unit = match.groups()
    number = float(number_str) if number_str else 0.0

    units = {'B': 1, 'KB': 1024, 'MB': 1024**2, 'GB': 1024**3}
    unit = unit.upper()

    # Convert the parsed values to integers
    if number_str and '.' in number_str:
        number = int(number * units[unit])
    else:
        number = int(number)

    return number

